(PKG/"core.py").write_text('from __future__ import annotations\nimport json,time\nfrom collections import defaultdict\nfrom pathlib import Path\n\nLIVE_PATHS=(\n "runtime_state/solana_opportunities/solana_scanner/phase8_strict_live_direct_economics.json",\n "runtime_state/solana_opportunities/solana_scanner/phase8_balanced_live_economics.json",\n)\nANCHORS={\n "So11111111111111111111111111111111111111112":"WSOL",\n "EPjFWdd5AufqSSqeM2qN1xzybapC8G4wEGGkZwyTDt1v":"USDC",\n "Es9vMFrzaCERmJfrF4H2FYD9zX6Y2pZPbBZ5w4M7ZC9":"USDT",\n}\nMAX_AGE_SECONDS=1.50\nMAX_CROSSVENUE_SKEW=0.50\nMIN_GROSS_BPS=8.0\nSUPPORTED={\n "PUMP_FUN","PUMP_SWAP","RAYDIUM_LAUNCHLAB","RAYDIUM_V4","RAYDIUM_CLMM","RAYDIUM_CPMM",\n "METEORA_DBC","METEORA_DAMM_V1","METEORA_DAMM_V2","METEORA_DLMM","ORCA",\n "MOONIT","BOOP_FUN","HEAVEN",\n}\n\ndef _rows(obj):\n    out=[]\n    def walk(x):\n        if isinstance(x,dict):\n            keys=set(x)\n            if {"input_asset","input_amount","output_asset","output_amount"}.issubset(keys):\n                out.append(x)\n            for v in x.values():\n                if isinstance(v,(dict,list)): walk(v)\n        elif isinstance(x,list):\n            for v in x: walk(v)\n    walk(obj)\n    return out\n\ndef normalize(x):\n    try:\n        fam=str(x.get("family") or x.get("venue") or "")\n        ia=float(x["input_amount"]);oa=float(x["output_amount"])\n        a=str(x["input_asset"]);b=str(x["output_asset"])\n        t=float(x.get("observed_unix") or x.get("trade_observed_unix") or 0.0)\n    except Exception:return None\n    if fam not in SUPPORTED or ia<=0 or oa<=0 or not a or not b or a==b or t<=0:return None\n    return {\n      "family":fam,"market_address":x.get("market_address"),"input_asset":a,"output_asset":b,\n      "input_amount":ia,"output_amount":oa,"rate":oa/ia,"observed_unix":t,\n      "trade_signature":x.get("trade_signature") or x.get("signature"),\n      "strict_live_provenance":bool(x.get("strict_live_provenance",True)),\n    }\n\nclass HotGraph:\n    def __init__(self):\n        self.edges={}\n        self.seen=set()\n\n    def ingest(self,rows,now=None):\n        now=time.time() if now is None else now\n        changed=set();new=0\n        for raw in rows:\n            x=normalize(raw)\n            if not x:continue\n            sig=x.get("trade_signature")\n            dedupe=(x["family"],sig,x["input_asset"],x["output_asset"],x["observed_unix"])\n            if dedupe in self.seen:continue\n            self.seen.add(dedupe)\n            k=(x["family"],x.get("market_address"),x["input_asset"],x["output_asset"])\n            cur=self.edges.get(k)\n            if cur is None or x["observed_unix"]>=cur["observed_unix"]:\n                self.edges[k]=x\n                changed.add(x["input_asset"]);changed.add(x["output_asset"]);new+=1\n        self.expire(now)\n        return new,changed\n\n    def expire(self,now=None):\n        now=time.time() if now is None else now\n        dead=[k for k,e in self.edges.items() if now-e["observed_unix"]>MAX_AGE_SECONDS]\n        for k in dead:self.edges.pop(k,None)\n\n    def _fresh(self,now=None):\n        now=time.time() if now is None else now\n        return [e for e in self.edges.values() if 0<=now-e["observed_unix"]<=MAX_AGE_SECONDS]\n\n    def two_leg(self,changed=None,now=None):\n        es=self._fresh(now);by_src=defaultdict(list)\n        for e in es:by_src[e["input_asset"]].append(e)\n        out=[]\n        starts=set(ANCHORS)\n        if changed: starts={a for a in starts if a in changed or any(e["output_asset"] in changed for e in by_src.get(a,[]))}\n        for a in starts:\n            for e1 in by_src.get(a,[]):\n                mid=e1["output_asset"]\n                for e2 in by_src.get(mid,[]):\n                    if e2["output_asset"]!=a or e2["family"]==e1["family"]:continue\n                    skew=abs(e2["observed_unix"]-e1["observed_unix"])\n                    if skew>MAX_CROSSVENUE_SKEW:continue\n                    mult=e1["rate"]*e2["rate"];bps=(mult-1.0)*10000.0\n                    if bps>=MIN_GROSS_BPS:\n                        out.append({"legs":2,"path":[a,mid,a],"families":[e1["family"],e2["family"]],\n                                    "gross_bps":bps,"skew_seconds":skew,"edges":[e1,e2]})\n        return sorted(out,key=lambda r:r["gross_bps"],reverse=True)\n\n    def three_leg(self,changed=None,now=None):\n        es=self._fresh(now);by_src=defaultdict(list)\n        for e in es:by_src[e["input_asset"]].append(e)\n        out=[]\n        for a in ANCHORS:\n            for e1 in by_src.get(a,[]):\n                x=e1["output_asset"]\n                for e2 in by_src.get(x,[]):\n                    y=e2["output_asset"]\n                    if y in (a,x):continue\n                    for e3 in by_src.get(y,[]):\n                        if e3["output_asset"]!=a:continue\n                        if len({e1["family"],e2["family"],e3["family"]})<2:continue\n                        ts=[e1["observed_unix"],e2["observed_unix"],e3["observed_unix"]]\n                        skew=max(ts)-min(ts)\n                        if skew>MAX_CROSSVENUE_SKEW:continue\n                        mult=e1["rate"]*e2["rate"]*e3["rate"];bps=(mult-1.0)*10000.0\n                        if bps>=MIN_GROSS_BPS:\n                            out.append({"legs":3,"path":[a,x,y,a],\n                                        "families":[e1["family"],e2["family"],e3["family"]],\n                                        "gross_bps":bps,"skew_seconds":skew,"edges":[e1,e2,e3]})\n        return sorted(out,key=lambda r:r["gross_bps"],reverse=True)\n\n    def scan_changed(self,changed=None,now=None):\n        t0=time.perf_counter_ns()\n        routes=self.two_leg(changed,now)+self.three_leg(changed,now)\n        routes.sort(key=lambda r:r["gross_bps"],reverse=True)\n        micros=(time.perf_counter_ns()-t0)/1000.0\n        return routes,micros\n\ndef read_changed(root,state):\n    rows=[];changed_files=[]\n    for rel in LIVE_PATHS:\n        p=Path(root)/rel\n        if not p.exists():continue\n        try:m=p.stat().st_mtime_ns\n        except OSError:continue\n        if state.get(rel)==m:continue\n        state[rel]=m\n        try:d=json.loads(p.read_text(encoding="utf-8"))\n        except Exception:continue\n        rows.extend(_rows(d));changed_files.append(rel)\n    return rows,changed_files\n',encoding="utf-8")
(PKG/"runtime.py").write_text('from __future__ import annotations\nimport json,time\nfrom pathlib import Path\nfrom .core import HotGraph,read_changed,ANCHORS\n\ndef _short(x):\n    return ANCHORS.get(x,x[:10])\n\ndef main():\n    root=Path.cwd();g=HotGraph();state={}\n    print("[QSB-047] EVENT-DRIVEN IN-MEMORY ARBITRAGE HOTGRAPH",flush=True)\n    print("[HOT_PATH] local file-change -> ingest -> affected 2-leg/3-leg graph recompute; ZERO quote/RPC calls",flush=True)\n    print("[SOURCE] existing Phase-8 strict/balanced live economics producer",flush=True)\n    print("[MODE] READ_ONLY=True execution_authority=FALSE",flush=True)\n    quiet=0\n    try:\n        while True:\n            rows,files=read_changed(root,state)\n            if rows:\n                now=time.time()\n                n,changed=g.ingest(rows,now)\n                routes,micros=g.scan_changed(changed,now)\n                print("[TICK] new=%d edges=%d files=%d recompute_us=%.1f routes=%d"%(\n                    n,len(g.edges),len(files),micros,len(routes)),flush=True)\n                for i,r in enumerate(routes[:8],1):\n                    print("[ARB_TRIGGER %d] legs=%d path=%s venues=%s gross_bps=%+.2f skew_ms=%.1f"%(\n                        i,r["legs"]," -> ".join(_short(x) for x in r["path"]),\n                        " -> ".join(r["families"]),r["gross_bps"],r["skew_seconds"]*1000.0),flush=True)\n                quiet=0\n            else:\n                quiet+=1\n                if quiet%500==0:\n                    print("[HEARTBEAT] edges=%d waiting_for_live_economic_update"%len(g.edges),flush=True)\n            time.sleep(.01)\n    except KeyboardInterrupt:\n        print("[STOP]",flush=True)\n\nif __name__=="__main__":main()\n',encoding="utf-8")
(ROOT/"test_qsb_047_event_driven_inmemory_hotgraph.py").write_text('import tempfile,time,unittest,json\nfrom pathlib import Path\nfrom qseries_v2.oracle_strategy_intelligence.solana_money.event_driven_hotgraph import core as c\nSOL="So11111111111111111111111111111111111111112"\ndef row(f,a,b,ia,oa,t,s):\n    return {"family":f,"input_asset":a,"output_asset":b,"input_amount":ia,"output_amount":oa,\n            "observed_unix":t,"trade_signature":s,"strict_live_provenance":True}\n\nclass T(unittest.TestCase):\n    def test_two_leg_crossvenue(self):\n        t=100.0;g=c.HotGraph()\n        rs=[row("PUMP_SWAP",SOL,"T",1,100,t,"1"),row("METEORA_DLMM","T",SOL,100,1.02,t+.1,"2")]\n        g.ingest(rs,100.2);r,u=g.scan_changed({SOL,"T"},100.2)\n        self.assertTrue(r);self.assertEqual(r[0]["legs"],2);self.assertGreater(r[0]["gross_bps"],190)\n        print("[PASS] 2-leg cross-venue arbitrage trigger")\n    def test_three_leg(self):\n        t=200.0;g=c.HotGraph()\n        rs=[row("RAYDIUM_CLMM",SOL,"A",1,10,t,"1"),row("ORCA","A","B",10,5,t+.1,"2"),\n            row("METEORA_DLMM","B",SOL,5,1.03,t+.2,"3")]\n        g.ingest(rs,200.3);r,u=g.scan_changed({SOL,"A","B"},200.3)\n        self.assertTrue(any(x["legs"]==3 for x in r))\n        print("[PASS] 3-leg triangular arbitrage trigger")\n    def test_stale_rejected(self):\n        g=c.HotGraph();g.ingest([row("PUMP_SWAP",SOL,"T",1,100,1,"1")],10)\n        self.assertFalse(g.edges)\n        print("[PASS] stale economics evicted")\n    def test_file_change_only(self):\n        with tempfile.TemporaryDirectory() as td:\n            old=c.LIVE_PATHS;c.LIVE_PATHS=("x.json",)\n            try:\n                p=Path(td)/"x.json";p.write_text(json.dumps({"rows":[row("ORCA",SOL,"T",1,2,time.time(),"1")]}))\n                st={};a,f=c.read_changed(td,st);b,f2=c.read_changed(td,st)\n                self.assertEqual(len(a),1);self.assertFalse(b)\n            finally:c.LIVE_PATHS=old\n        print("[PASS] unchanged artifacts do not trigger recompute")\n    def test_hot_recompute_latency(self):\n        now=500.0;g=c.HotGraph()\n        rs=[]\n        for i in range(500):\n            rs.append(row("PUMP_SWAP" if i%2==0 else "RAYDIUM_CPMM",SOL,f"T{i}",1,100+i,now,f"A{i}"))\n        g.ingest(rs,now);_,u=g.scan_changed({SOL},now)\n        self.assertLess(u,50000)\n        print("[PASS] in-memory route recompute under 50ms fixture gate: %.1fus"%u)\n\nif __name__=="__main__":unittest.main(verbosity=2)\n',encoding="utf-8")
